1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Function;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Every domain table, child-before-parent. Referential integrity is dropped around the
34	     * TRUNCATE so the order is only for readability of the FK chain (invoices -> projects ->
35	     * clients). Add a new table here (and a matching {@code seedTable} call) to extend the harness.
36	     */
37	    private static final List<String> TABLES =
38	            List.of("invoice_line_items", "invoices", "notes", "tasks", "contacts", "project_tags",
39	                    "projects", "tags", "clients");
40	
41	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
42	    @PostMapping("/reset")
43	    public void reset() {
44	        audit.clear();
45	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
46	        for (String table : TABLES) {
47	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
48	        }
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    public void seed(@RequestBody Map<String, Object> fixture) {
55	        seedTable(fixture, "clients", "INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
56	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email")});
57	        seedTable(fixture, "projects", "INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
58	                p -> new Object[] {id(p, "id"), p.get("name"), id(p, "clientId")});
59	        seedTable(fixture, "contacts",
60	                "INSERT INTO contacts (id, name, email, role, client_id) VALUES (?, ?, ?, ?, ?)",
61	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email"), c.get("role"),
62	                        id(c, "clientId")});
63	        seedTable(fixture, "tasks", "INSERT INTO tasks (id, title, done, project_id) VALUES (?, ?, ?, ?)",
64	                t -> new Object[] {id(t, "id"), t.get("title"), Boolean.TRUE.equals(t.get("done")),
65	                        id(t, "projectId")});
66	        seedTable(fixture, "notes",
67	                "INSERT INTO notes (id, target_type, target_id, note_text, noted_at) VALUES (?, ?, ?, ?, ?)",
68	                n -> new Object[] {id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
69	                        n.get("at")});
70	        // Notes are pre-seeded AND created through the API in the same spec, so the identity has to
71	        // continue past the seeded ids (a raw insert of an explicit id does not advance H2's
72	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
73	        restartIdentity("notes");
74	        seedTable(fixture, "tags", "INSERT INTO tags (id, name) VALUES (?, ?)",
75	                t -> new Object[] {id(t, "id"), t.get("name")});
76	        seedTable(fixture, "projectTags",
77	                "INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
78	                pt -> new Object[] {id(pt, "projectId"), id(pt, "tagId")});
79	        seedInvoices(fixture);
80	    }
81	
82	    /**
83	     * Seed invoices and, nested under each, its line items. An invoice's amount is the sum of its
84	     * lines' qty * unitPrice, so when a fixture lists {@code lineItems} the amount is derived from
85	     * them (the user no longer types one figure); a fixture may still give an explicit
86	     * {@code amount} instead (an invoice with no lines). One method rather than a plain seedTable
87	     * call because the line items live inside each invoice, keyed by the invoice's own id.
88	     */
89	    @SuppressWarnings("unchecked")
90	    private void seedInvoices(Map<String, Object> fixture) {
91	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
92	        if (invoices == null) {
93	            return;
94	        }
95	        for (Map<String, Object> invoice : invoices) {
96	            long invoiceId = id(invoice, "id");
97	            List<Map<String, Object>> lineItems =
98	                    (List<Map<String, Object>>) invoice.get("lineItems");
99	            double amount;
100	            if (invoice.get("amount") != null) {
101	                amount = ((Number) invoice.get("amount")).doubleValue();
102	            } else {
103	                amount = 0.0;
104	                if (lineItems != null) {
105	                    for (Map<String, Object> line : lineItems) {
106	                        amount += ((Number) line.get("qty")).doubleValue()
107	                                * ((Number) line.get("unitPrice")).doubleValue();
108	                    }
109	                }
110	            }
111	            jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
112	                    + " VALUES (?, ?, ?, ?, ?, ?)",
113	                    invoiceId, id(invoice, "projectId"), amount,
114	                    invoice.getOrDefault("status", "DRAFT"), invoice.get("issuedDate"),
115	                    invoice.get("dueDate"));
